print(fx.symbolic_trace(Foo()).graph)

graph():
    %x : [#users=1] = placeholder[target=x]
    %mod1 : [#users=1] = call_module[target=mod1](args = (%x,), kwargs = {})
    return mod1

For an example of when this might be needed:
class Foo(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.mod1 = torch.nn.Linear(1, 1)
    def forward(self, x, y):
        z = self.mod1(y)
        if z.sum() > 0:
            return x
        else:
            return 2*x

print(fx.symbolic_trace(Foo(), concrete_args={'y': torch.randn(1)}).graph)

A full example of a FX model that's not traceable because of this is here: https://github.com/huggingface/transformers/blob/632bdd58bc1f017728cf17b2ad295892ebb9e00d/src/transformers/models/t5/modeling_t5.py#L1405
